using System.Text.Json;

namespace Facilitator.Tests.ScenarioGate;

/// <summary>
/// The scenario gate's fail-closed law over its own manifest
/// (<c>docs/scenarios/scenario-bindings.json</c>, generated by
/// <c>tools/scenario-plane/gen-bindings.py</c> and hand-reviewed):
/// every approved scenario carries a verdict, every dotnet evidence id is a
/// method that exists on a class in THIS assembly right now, every js
/// evidence path exists on disk, and the manifest covers exactly the ids in
/// <c>approved-scenarios.md</c>. A renamed test or a deleted scenario turns
/// the gate red instead of quietly rotting the audit record.
/// </summary>
public class ScenarioBindingsTests
{
    private static readonly string RepoRoot = FindRepoRoot();

    private static string FindRepoRoot()
    {
        var dir = new DirectoryInfo(AppContext.BaseDirectory);
        while (dir is not null && !File.Exists(Path.Combine(dir.FullName, "OpenFacilitator.slnx")))
        {
            dir = dir.Parent;
        }

        return dir?.FullName ?? throw new DirectoryNotFoundException("repository root with OpenFacilitator.slnx");
    }

    private sealed record Binding(string Id, string Family, string Tier, string Title,
        string Verdict, string Lane, string[] Evidence, string Note);

    private static List<Binding> Load()
    {
        var path = Path.Combine(RepoRoot, "docs", "scenarios", "scenario-bindings.json");
        using var doc = JsonDocument.Parse(File.ReadAllText(path));
        var list = new List<Binding>();
        foreach (var e in doc.RootElement.GetProperty("scenarios").EnumerateArray())
        {
            list.Add(new Binding(
                e.GetProperty("id").GetString()!,
                e.GetProperty("family").GetString()!,
                e.GetProperty("tier").GetString()!,
                e.GetProperty("title").GetString()!,
                e.GetProperty("verdict").GetString()!,
                e.GetProperty("lane").GetString()!,
                e.GetProperty("evidence").EnumerateArray().Select(x => x.GetString()!).ToArray(),
                e.GetProperty("note").GetString()!));
        }

        return list;
    }

    public static TheoryData<string> ScenarioIds() =>
        new(Load().Select(b => (string)b.Id).ToArray());

    [Theory]
    [MemberData(nameof(ScenarioIds))]
    public void EveryEvidenceIdResolves(string id)
    {
        var b = Load().Single(x => x.Id == id);
        Assert.Contains(b.Verdict, new[]
        {
            "covered", "partial", "absent", "silent-absent", "divergent", "unexpressible", "environment-blocked",
        });
        if (b.Verdict is "covered" or "partial")
        {
            Assert.NotEmpty(b.Evidence);
        }

        foreach (var ev in b.Evidence)
        {
            if (ev.StartsWith("js:", StringComparison.Ordinal))
            {
                Assert.True(File.Exists(Path.Combine(RepoRoot, ev[3..])),
                    $"{id}: js evidence missing on disk: {ev}");
                continue;
            }

            var (typeName, methodName) = ev.LastIndexOf('.') switch
            {
                < 0 => throw new InvalidOperationException($"{id}: evidence `{ev}` is not Class.Method"),
                var i => (ev[..i], ev[(i + 1)..]),
            };
            var type = typeof(ScenarioBindingsTests).Assembly
                .GetTypes()
                // The artifact family ships an abstract `<Name>TestsBase` with
                // Fs/S3 concrete twins; the evidence names the family, so any
                // of those spellings resolves (FirstOrDefault: the Fs twin
                // and the base both carry the method).
                .FirstOrDefault(t =>
                    t.Name == typeName || t.FullName == typeName
                    || t.Name == $"{typeName}Base" || t.Name == $"Fs{typeName}" || t.Name == $"S3{typeName}");
            if (type is null)
            {
                throw new InvalidDataException($"{id}: no type resolves for `{typeName}`");
            }

            if (type.GetMethod(methodName) is null)
            {
                throw new InvalidDataException($"{id}: `{typeName}` has no method `{methodName}`");
            }
        }
    }

    [Fact]
    public void ManifestCoversTheCatalogExactly()
    {
        var catalog = File.ReadAllText(Path.Combine(RepoRoot, "docs", "scenarios", "approved-scenarios.md"));
        var positives = System.Text.RegularExpressions.Regex
            .Matches(catalog, @"^### ([A-Z]\d+) —", System.Text.RegularExpressions.RegexOptions.Multiline)
            .Select(m => m.Groups[1].Value).ToList();
        var negatives = System.Text.RegularExpressions.Regex
            .Matches(catalog, @"^\| (N\d+) \|", System.Text.RegularExpressions.RegexOptions.Multiline)
            .Select(m => m.Groups[1].Value).ToList();
        var want = positives.Concat(negatives).Order(StringComparer.Ordinal).ToList();
        var have = Load().Select(b => b.Id).Order(StringComparer.Ordinal).ToList();
        Assert.Equal(want, have);
    }

    [Fact]
    public void ManualLaneMatchesTiers()
    {
        foreach (var b in Load())
        {
            if (b.Tier == "T4")
            {
                Assert.Equal("T4-manual", b.Lane);
            }
            else
            {
                Assert.NotEqual("T4-manual", b.Lane);
            }
        }
    }
}
